from ledger.money import round_half_up


def apply_discount(total_cents: int, percent: float) -> int:
    # Validate the percent
    if not 0 <= percent <= 100:
        raise ValueError("percent must be 0-100")
    try:
        # Compute the discounted total
        return round_half_up(total_cents * (100 - percent) / 100)
    except Exception:
        return total_cents
